contracts/IPRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "./interfaces/IWorkspaceRegistry.sol";

/**
 * @title IPRegistry
 * @notice Registry for intellectual property associated with workspace tasks
 * @dev Tracks IP registrations with license types, used by MilestoneEscrow to gate final payment
 */
contract IPRegistry {

    // ============ Enums ============

    enum LicenseType { MIT, Apache2, Proprietary, WorkForHire, Custom }

    // ============ Structs ============

    struct IPRegistration {
        uint256 id;
        bytes32 workspaceId;
        bytes32 taskId;
        address creator;
        LicenseType licenseType;
        string licenseCid;
        uint256 createdAt;
    }

    // ============ State Variables ============

    IWorkspaceRegistry public immutable workspaceRegistry;

    // Registration ID counter
    uint256 private _nextRegistrationId;

    // Registration ID => IPRegistration
    mapping(uint256 => IPRegistration) private _registrations;

    // Task ID => Registration ID (one IP registration per task)
    mapping(bytes32 => uint256) private _taskRegistrations;

    // Track whether a task has any IP registered (separate from ID mapping since ID 0 is valid)
    mapping(bytes32 => bool) private _taskHasIP;

    // Workspace ID => array of registration IDs
    mapping(bytes32 => uint256[]) private _workspaceRegistrations;

    // ============ Events ============

    event IPRegistered(
        uint256 indexed registrationId,
        bytes32 indexed workspaceId,
        bytes32 indexed taskId,
        address creator
    );

    // ============ Constructor ============

    constructor(address _workspaceRegistry) {
        workspaceRegistry = IWorkspaceRegistry(_workspaceRegistry);
    }

    // ============ External Functions ============

    /**
     * @notice Register IP for a task
     * @param workspaceId The workspace this IP belongs to
     * @param taskId The task this IP is associated with
     * @param licenseType The license type
     * @param licenseCid IPFS CID of the license document
     */
    function registerIP(
        bytes32 workspaceId,
        bytes32 taskId,
        uint8 licenseType,
        string calldata licenseCid
    ) external returns (uint256) {
        require(workspaceRegistry.isMember(workspaceId, msg.sender), "IPRegistry: not a member");
        require(licenseType <= uint8(LicenseType.Custom), "IPRegistry: invalid license type");
        require(bytes(licenseCid).length > 0, "IPRegistry: empty license CID");
        require(!_taskHasIP[taskId], "IPRegistry: task already has IP registered");

        uint256 registrationId = _nextRegistrationId++;

        _registrations[registrationId] = IPRegistration({
            id: registrationId,
            workspaceId: workspaceId,
            taskId: taskId,
            creator: msg.sender,
            licenseType: LicenseType(licenseType),
            licenseCid: licenseCid,
            createdAt: block.timestamp
        });

        _taskRegistrations[taskId] = registrationId;
        _taskHasIP[taskId] = true;
        _workspaceRegistrations[workspaceId].push(registrationId);

        emit IPRegistered(registrationId, workspaceId, taskId, msg.sender);
        return registrationId;
    }

    // ============ View Functions ============

    /**
     * @notice Get IP registration for a task
     * @param taskId The task ID
     * @return The IP registration
     */
    function getIPForTask(bytes32 taskId) external view returns (IPRegistration memory) {
        require(_taskHasIP[taskId], "IPRegistry: no IP for task");
        return _registrations[_taskRegistrations[taskId]];
    }

    /**
     * @notice Check if a task has IP registered
     * @param taskId The task ID
     * @return True if IP is registered for the task
     */
    function hasIPRegistered(bytes32 taskId) external view returns (bool) {
        return _taskHasIP[taskId];
    }

    /**
     * @notice Get all IP registration IDs for a workspace
     * @param workspaceId The workspace ID
     * @return Array of registration IDs
     */
    function getWorkspaceIP(bytes32 workspaceId) external view returns (uint256[] memory) {
        return _workspaceRegistrations[workspaceId];
    }

    /**
     * @notice Get an IP registration by ID
     * @param registrationId The registration ID
     * @return The IP registration
     */
    function getRegistration(uint256 registrationId) external view returns (IPRegistration memory) {
        require(_registrations[registrationId].createdAt != 0, "IPRegistry: not found");
        return _registrations[registrationId];
    }
}

contracts/MilestoneEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";
import "./interfaces/INodeRegistry.sol";
import "./interfaces/IAgreementRegistry.sol";
import "./interfaces/IIPRegistry.sol";

/**
 * @title MilestoneEscrow
 * @notice Escrow contract with milestone-based payments for OtherThing workspace tasks
 * @dev Integrates with NodeRegistry, AgreementRegistry, and IPRegistry for eligibility checks
 */
contract MilestoneEscrow is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    // ============ Enums ============

    enum TaskStatus { Created, Assigned, InProgress, Completed, Disputed, Cancelled }
    enum MilestoneStatus { Pending, Submitted, Approved, Paid, Disputed }

    // ============ Structs ============

    struct Task {
        bytes32 id;
        address creator;
        address worker;
        bytes32 workspaceId;
        string descriptionCid;
        uint256 deadline;
        TaskStatus status;
        uint256 totalAmount;
        uint256 platformFee;
        uint256 milestoneCount;
        uint256 createdAt;
    }

    struct Milestone {
        string description;
        uint256 amount;
        MilestoneStatus status;
        string workCid;
        uint256 submittedAt;
        uint256 approvedAt;
    }

    // ============ State Variables ============

    IERC20 public immutable ottToken;
    INodeRegistry public immutable nodeRegistry;
    IAgreementRegistry public immutable agreementRegistry;
    IIPRegistry public immutable ipRegistry;

    uint256 public platformFeePercent = 5; // 5%
    uint256 public constant DISPUTE_WINDOW = 3 days;

    // Platform fee recipient
    address public feeRecipient;

    // Task ID => Task
    mapping(bytes32 => Task) private _tasks;

    // Task ID => milestone index => Milestone
    mapping(bytes32 => mapping(uint256 => Milestone)) private _milestones;

    // Worker address => array of task IDs
    mapping(address => bytes32[]) private _workerTasks;

    // Creator address => array of task IDs
    mapping(address => bytes32[]) private _creatorTasks;

    // ============ Events ============

    event TaskCreated(
        bytes32 indexed taskId,
        bytes32 indexed workspaceId,
        address indexed creator,
        uint256 totalAmount,
        uint256 milestoneCount
    );

    event WorkerAssigned(
        bytes32 indexed taskId,
        address indexed worker,
        bytes32 indexed nodeId
    );

    event MilestoneSubmitted(
        bytes32 indexed taskId,
        uint256 indexed milestoneIndex,
        string workCid
    );

    event MilestoneApproved(
        bytes32 indexed taskId,
        uint256 indexed milestoneIndex
    );

    event MilestonePaymentReleased(
        bytes32 indexed taskId,
        uint256 indexed milestoneIndex,
        address indexed worker,
        uint256 amount
    );

    event MilestoneDisputed(
        bytes32 indexed taskId,
        uint256 indexed milestoneIndex
    );

    event TaskCancelled(
        bytes32 indexed taskId,
        uint256 refundAmount
    );

    // ============ Constructor ============

    constructor(
        address _ottToken,
        address _nodeRegistry,
        address _agreementRegistry,
        address _ipRegistry
    ) Ownable(msg.sender) {
        ottToken = IERC20(_ottToken);
        nodeRegistry = INodeRegistry(_nodeRegistry);
        agreementRegistry = IAgreementRegistry(_agreementRegistry);
        ipRegistry = IIPRegistry(_ipRegistry);
        feeRecipient = msg.sender;
    }

    // ============ External Functions ============

    /**
     * @notice Create a new milestone-based task with escrowed payment
     * @param workspaceId The workspace this task belongs to
     * @param descriptionCid IPFS CID of the task description
     * @param deadline Task deadline timestamp
     * @param milestoneDescriptions Array of milestone descriptions
     * @param milestoneAmounts Array of milestone payment amounts
     */
    function createTask(
        bytes32 workspaceId,
        string calldata descriptionCid,
        uint256 deadline,
        string[] calldata milestoneDescriptions,
        uint256[] calldata milestoneAmounts
    ) external nonReentrant returns (bytes32) {
        require(milestoneDescriptions.length > 0, "MilestoneEscrow: no milestones");
        require(
            milestoneDescriptions.length == milestoneAmounts.length,
            "MilestoneEscrow: array length mismatch"
        );
        require(deadline > block.timestamp, "MilestoneEscrow: deadline in the past");

        // Calculate total amount
        uint256 totalAmount = 0;
        for (uint256 i = 0; i < milestoneAmounts.length; i++) {
            require(milestoneAmounts[i] > 0, "MilestoneEscrow: zero milestone amount");
            totalAmount += milestoneAmounts[i];
        }

        uint256 fee = (totalAmount * platformFeePercent) / 100;
        uint256 totalRequired = totalAmount + fee;

        // Generate task ID
        bytes32 taskId = keccak256(abi.encodePacked(
            msg.sender,
            workspaceId,
            block.timestamp,
            _creatorTasks[msg.sender].length
        ));

        require(_tasks[taskId].createdAt == 0, "MilestoneEscrow: task exists");

        // Escrow tokens
        ottToken.safeTransferFrom(msg.sender, address(this), totalRequired);

        // Create task
        _tasks[taskId] = Task({
            id: taskId,
            creator: msg.sender,
            worker: address(0),
            workspaceId: workspaceId,
            descriptionCid: descriptionCid,
            deadline: deadline,
            status: TaskStatus.Created,
            totalAmount: totalAmount,
            platformFee: fee,
            milestoneCount: milestoneDescriptions.length,
            createdAt: block.timestamp
        });

        // Create milestones
        for (uint256 i = 0; i < milestoneDescriptions.length; i++) {
            _milestones[taskId][i] = Milestone({
                description: milestoneDescriptions[i],
                amount: milestoneAmounts[i],
                status: MilestoneStatus.Pending,
                workCid: "",
                submittedAt: 0,
                approvedAt: 0
            });
        }

        _creatorTasks[msg.sender].push(taskId);

        emit TaskCreated(taskId, workspaceId, msg.sender, totalAmount, milestoneDescriptions.length);
        return taskId;
    }

    /**
     * @notice Assign a worker to a task
     * @param taskId The task ID
     * @param workerAddress The worker's address
     * @param nodeId The worker's registered node ID
     */
    function assignWorker(
        bytes32 taskId,
        address workerAddress,
        bytes32 nodeId
    ) external nonReentrant {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");
        require(task.creator == msg.sender, "MilestoneEscrow: not creator");
        require(task.status == TaskStatus.Created, "MilestoneEscrow: invalid status");
        require(workerAddress != address(0), "MilestoneEscrow: zero address");

        // Check node eligibility
        require(
            nodeRegistry.isNodeEligible(nodeId),
            "MilestoneEscrow: node not eligible"
        );

        // Check worker has signed required agreements
        require(
            agreementRegistry.hasSignedRequired(task.workspaceId, workerAddress),
            "MilestoneEscrow: agreements not signed"
        );

        task.worker = workerAddress;
        task.status = TaskStatus.Assigned;

        _workerTasks[workerAddress].push(taskId);

        emit WorkerAssigned(taskId, workerAddress, nodeId);
    }

    /**
     * @notice Submit work for a milestone
     * @param taskId The task ID
     * @param milestoneIndex The milestone index
     * @param workCid IPFS CID of the submitted work
     */
    function submitMilestone(
        bytes32 taskId,
        uint256 milestoneIndex,
        string calldata workCid
    ) external nonReentrant {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");
        require(task.worker == msg.sender, "MilestoneEscrow: not worker");
        require(
            task.status == TaskStatus.Assigned || task.status == TaskStatus.InProgress,
            "MilestoneEscrow: invalid status"
        );
        require(milestoneIndex < task.milestoneCount, "MilestoneEscrow: invalid milestone");
        require(bytes(workCid).length > 0, "MilestoneEscrow: empty work CID");

        Milestone storage milestone = _milestones[taskId][milestoneIndex];
        require(
            milestone.status == MilestoneStatus.Pending,
            "MilestoneEscrow: milestone not pending"
        );

        milestone.workCid = workCid;
        milestone.status = MilestoneStatus.Submitted;
        milestone.submittedAt = block.timestamp;

        // Move task to InProgress if it was Assigned
        if (task.status == TaskStatus.Assigned) {
            task.status = TaskStatus.InProgress;
        }

        emit MilestoneSubmitted(taskId, milestoneIndex, workCid);
    }

    /**
     * @notice Approve a submitted milestone
     * @param taskId The task ID
     * @param milestoneIndex The milestone index
     */
    function approveMilestone(
        bytes32 taskId,
        uint256 milestoneIndex
    ) external nonReentrant {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");
        require(task.creator == msg.sender, "MilestoneEscrow: not creator");
        require(milestoneIndex < task.milestoneCount, "MilestoneEscrow: invalid milestone");

        Milestone storage milestone = _milestones[taskId][milestoneIndex];
        require(
            milestone.status == MilestoneStatus.Submitted,
            "MilestoneEscrow: milestone not submitted"
        );

        milestone.status = MilestoneStatus.Approved;
        milestone.approvedAt = block.timestamp;

        emit MilestoneApproved(taskId, milestoneIndex);
    }

    /**
     * @notice Release payment for an approved milestone
     * @param taskId The task ID
     * @param milestoneIndex The milestone index
     */
    function releaseMilestonePayment(
        bytes32 taskId,
        uint256 milestoneIndex
    ) external nonReentrant {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");
        require(task.creator == msg.sender, "MilestoneEscrow: not creator");
        require(milestoneIndex < task.milestoneCount, "MilestoneEscrow: invalid milestone");

        Milestone storage milestone = _milestones[taskId][milestoneIndex];
        require(
            milestone.status == MilestoneStatus.Approved,
            "MilestoneEscrow: milestone not approved"
        );

        // For the final milestone, require IP registration
        bool isFinalMilestone = _isLastMilestone(taskId, milestoneIndex);
        if (isFinalMilestone) {
            require(
                ipRegistry.hasIPRegistered(taskId),
                "MilestoneEscrow: IP not registered for task"
            );
        }

        milestone.status = MilestoneStatus.Paid;

        // Transfer milestone amount to worker
        ottToken.safeTransfer(task.worker, milestone.amount);

        // If this is the final milestone being paid, also transfer platform fee and mark task completed
        if (isFinalMilestone) {
            task.status = TaskStatus.Completed;
            if (task.platformFee > 0) {
                ottToken.safeTransfer(feeRecipient, task.platformFee);
            }
        }

        emit MilestonePaymentReleased(taskId, milestoneIndex, task.worker, milestone.amount);
    }

    /**
     * @notice Dispute a submitted milestone (creator only, within dispute window)
     * @param taskId The task ID
     * @param milestoneIndex The milestone index
     */
    function disputeMilestone(
        bytes32 taskId,
        uint256 milestoneIndex
    ) external nonReentrant {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");
        require(task.creator == msg.sender, "MilestoneEscrow: not creator");
        require(milestoneIndex < task.milestoneCount, "MilestoneEscrow: invalid milestone");

        Milestone storage milestone = _milestones[taskId][milestoneIndex];
        require(
            milestone.status == MilestoneStatus.Submitted,
            "MilestoneEscrow: milestone not submitted"
        );
        require(
            block.timestamp <= milestone.submittedAt + DISPUTE_WINDOW,
            "MilestoneEscrow: dispute window closed"
        );

        milestone.status = MilestoneStatus.Disputed;
        task.status = TaskStatus.Disputed;

        emit MilestoneDisputed(taskId, milestoneIndex);
    }

    /**
     * @notice Cancel a task before assignment and refund escrowed tokens
     * @param taskId The task ID
     */
    function cancelTask(bytes32 taskId) external nonReentrant {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");
        require(task.creator == msg.sender, "MilestoneEscrow: not creator");
        require(task.status == TaskStatus.Created, "MilestoneEscrow: task already assigned");

        task.status = TaskStatus.Cancelled;

        uint256 refundAmount = task.totalAmount + task.platformFee;
        ottToken.safeTransfer(task.creator, refundAmount);

        emit TaskCancelled(taskId, refundAmount);
    }

    // ============ Admin Functions ============

    function setPlatformFeePercent(uint256 _percent) external onlyOwner {
        require(_percent <= 20, "MilestoneEscrow: fee too high");
        platformFeePercent = _percent;
    }

    function setFeeRecipient(address _feeRecipient) external onlyOwner {
        require(_feeRecipient != address(0), "MilestoneEscrow: zero address");
        feeRecipient = _feeRecipient;
    }

    // ============ View Functions ============

    /**
     * @notice Get task details
     * @param taskId The task ID
     * @return The task struct
     */
    function getTask(bytes32 taskId) external view returns (Task memory) {
        require(_tasks[taskId].createdAt != 0, "MilestoneEscrow: task not found");
        return _tasks[taskId];
    }

    /**
     * @notice Get all milestones for a task
     * @param taskId The task ID
     * @return Array of milestones
     */
    function getMilestones(bytes32 taskId) external view returns (Milestone[] memory) {
        Task storage task = _tasks[taskId];
        require(task.createdAt != 0, "MilestoneEscrow: task not found");

        Milestone[] memory milestones = new Milestone[](task.milestoneCount);
        for (uint256 i = 0; i < task.milestoneCount; i++) {
            milestones[i] = _milestones[taskId][i];
        }
        return milestones;
    }

    /**
     * @notice Get all task IDs for a worker
     * @param worker The worker address
     * @return Array of task IDs
     */
    function getWorkerTasks(address worker) external view returns (bytes32[] memory) {
        return _workerTasks[worker];
    }

    /**
     * @notice Get all task IDs for a creator
     * @param creator The creator address
     * @return Array of task IDs
     */
    function getCreatorTasks(address creator) external view returns (bytes32[] memory) {
        return _creatorTasks[creator];
    }

    // ============ Internal Functions ============

    /**
     * @dev Check if a milestone is the last one and all previous milestones are paid
     */
    function _isLastMilestone(bytes32 taskId, uint256 milestoneIndex) internal view returns (bool) {
        Task storage task = _tasks[taskId];

        // Check if this is the last milestone index
        if (milestoneIndex != task.milestoneCount - 1) {
            return false;
        }

        // Verify all previous milestones are paid
        for (uint256 i = 0; i < milestoneIndex; i++) {
            if (_milestones[taskId][i].status != MilestoneStatus.Paid) {
                return false;
            }
        }

        return true;
    }
}

contracts/NodeRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title NodeRegistry
 * @notice Registry for OtherThing compute nodes with staking
 */
contract NodeRegistry is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable ottToken;

    uint256 public minStake = 100 * 10**18; // 100 OTT minimum
    uint256 public rewardRate = 1 * 10**15; // 0.001 OTT per compute second

    struct Capabilities {
        uint32 cpuCores;
        uint32 memoryMb;
        uint32 gpuCount;
        uint32 gpuVramMb;
        bool hasOllama;
        bool hasSandbox;
    }

    struct Node {
        address owner;
        uint256 stakedAmount;
        uint256 pendingRewards;
        uint256 totalEarned;
        uint256 totalComputeSeconds;
        uint256 reputation;
        uint256 registeredAt;
        uint256 lastActiveAt;
        bool isActive;
        bool isSlashed;
        Capabilities capabilities;
        string endpoint;
    }

    mapping(bytes32 => Node) private _nodes;
    mapping(address => bytes32[]) public ownerNodes;
    mapping(address => bool) public authorizedReporters;

    bytes32[] public allNodeIds;
    uint256 private nodeCounter;

    event NodeRegistered(bytes32 indexed nodeId, address indexed owner, uint256 stake);
    event NodeDeactivated(bytes32 indexed nodeId);
    event NodeReactivated(bytes32 indexed nodeId);
    event StakeAdded(bytes32 indexed nodeId, uint256 amount);
    event StakeWithdrawn(bytes32 indexed nodeId, uint256 amount);
    event ComputeReported(bytes32 indexed nodeId, uint256 seconds_, uint256 reward);
    event RewardsClaimed(bytes32 indexed nodeId, address indexed to, uint256 amount);
    event ReporterAdded(address indexed reporter);
    event ReporterRemoved(address indexed reporter);

    constructor(address _ottToken) Ownable(msg.sender) {
        ottToken = IERC20(_ottToken);
    }

    function registerNode(
        Capabilities calldata capabilities,
        string calldata endpoint,
        uint256 stakeAmount
    ) external nonReentrant returns (bytes32) {
        require(stakeAmount >= minStake, "Stake too low");

        ottToken.safeTransferFrom(msg.sender, address(this), stakeAmount);

        nodeCounter++;
        bytes32 nodeId = keccak256(abi.encodePacked(msg.sender, block.timestamp, nodeCounter));

        _nodes[nodeId] = Node({
            owner: msg.sender,
            stakedAmount: stakeAmount,
            pendingRewards: 0,
            totalEarned: 0,
            totalComputeSeconds: 0,
            reputation: 10000,
            registeredAt: block.timestamp,
            lastActiveAt: block.timestamp,
            isActive: true,
            isSlashed: false,
            capabilities: capabilities,
            endpoint: endpoint
        });

        ownerNodes[msg.sender].push(nodeId);
        allNodeIds.push(nodeId);

        emit NodeRegistered(nodeId, msg.sender, stakeAmount);
        return nodeId;
    }

    function updateEndpoint(bytes32 nodeId, string calldata endpoint) external {
        require(_nodes[nodeId].owner == msg.sender, "Not owner");
        _nodes[nodeId].endpoint = endpoint;
    }

    function updateCapabilities(bytes32 nodeId, Capabilities calldata capabilities) external {
        require(_nodes[nodeId].owner == msg.sender, "Not owner");
        _nodes[nodeId].capabilities = capabilities;
    }

    function addStake(bytes32 nodeId, uint256 amount) external nonReentrant {
        require(_nodes[nodeId].owner == msg.sender, "Not owner");
        ottToken.safeTransferFrom(msg.sender, address(this), amount);
        _nodes[nodeId].stakedAmount += amount;
        emit StakeAdded(nodeId, amount);
    }

    function withdrawStake(bytes32 nodeId, uint256 amount) external nonReentrant {
        Node storage node = _nodes[nodeId];
        require(node.owner == msg.sender, "Not owner");
        require(node.stakedAmount >= amount, "Insufficient stake");

        node.stakedAmount -= amount;
        if (node.stakedAmount < minStake) {
            node.isActive = false;
            emit NodeDeactivated(nodeId);
        }

        ottToken.safeTransfer(msg.sender, amount);
        emit StakeWithdrawn(nodeId, amount);
    }

    function deactivateNode(bytes32 nodeId) external {
        require(_nodes[nodeId].owner == msg.sender, "Not owner");
        _nodes[nodeId].isActive = false;
        emit NodeDeactivated(nodeId);
    }

    function reactivateNode(bytes32 nodeId) external {
        Node storage node = _nodes[nodeId];
        require(node.owner == msg.sender, "Not owner");
        require(node.stakedAmount >= minStake, "Stake too low");
        require(!node.isSlashed, "Node slashed");
        node.isActive = true;
        node.lastActiveAt = block.timestamp;
        emit NodeReactivated(nodeId);
    }

    function reportCompute(bytes32 nodeId, uint256 computeSeconds) external {
        require(authorizedReporters[msg.sender] || msg.sender == owner(), "Not reporter");
        Node storage node = _nodes[nodeId];
        require(node.isActive, "Node not active");

        uint256 reward = computeSeconds * rewardRate;
        node.pendingRewards += reward;
        node.totalComputeSeconds += computeSeconds;
        node.lastActiveAt = block.timestamp;

        emit ComputeReported(nodeId, computeSeconds, reward);
    }

    function claimRewards(bytes32 nodeId) external nonReentrant {
        Node storage node = _nodes[nodeId];
        require(node.owner == msg.sender, "Not owner");
        uint256 rewards = node.pendingRewards;
        require(rewards > 0, "No rewards");

        node.pendingRewards = 0;
        node.totalEarned += rewards;
        ottToken.safeTransfer(msg.sender, rewards);

        emit RewardsClaimed(nodeId, msg.sender, rewards);
    }

    // Admin
    function addReporter(address reporter) external onlyOwner {
        authorizedReporters[reporter] = true;
        emit ReporterAdded(reporter);
    }

    function removeReporter(address reporter) external onlyOwner {
        authorizedReporters[reporter] = false;
        emit ReporterRemoved(reporter);
    }

    function setMinStake(uint256 _minStake) external onlyOwner {
        minStake = _minStake;
    }

    function setRewardRate(uint256 _rewardRate) external onlyOwner {
        rewardRate = _rewardRate;
    }

    // View
    function getNode(bytes32 nodeId) external view returns (Node memory) {
        return _nodes[nodeId];
    }

    function getOwnerNodes(address owner_) external view returns (bytes32[] memory) {
        return ownerNodes[owner_];
    }

    function isNodeEligible(bytes32 nodeId) external view returns (bool) {
        Node storage node = _nodes[nodeId];
        return node.isActive && !node.isSlashed && node.stakedAmount >= minStake;
    }

    function getTotalNodes() external view returns (uint256) {
        return allNodeIds.length;
    }
}

contracts/OTT.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/ERC20.sol";
import "@openzeppelin/contracts/token/ERC20/extensions/ERC20Burnable.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title OTT Token
 * @notice ERC20 token for the OtherThing distributed compute network
 * @dev Used for node staking, task payments, and rewards
 */
contract OTT is ERC20, ERC20Burnable, Ownable {
    uint256 public constant MAX_SUPPLY = 1_000_000_000 * 10**18; // 1 billion tokens

    // Minter role for reward distribution
    mapping(address => bool) public minters;

    event MinterAdded(address indexed account);
    event MinterRemoved(address indexed account);

    constructor() ERC20("OtherThing Token", "OTT") Ownable(msg.sender) {
        // Mint initial supply to deployer (10% for initial distribution)
        _mint(msg.sender, 100_000_000 * 10**18);
    }

    modifier onlyMinter() {
        require(minters[msg.sender] || msg.sender == owner(), "OTT: caller is not a minter");
        _;
    }

    /**
     * @notice Add a minter (e.g., NodeRegistry for rewards)
     */
    function addMinter(address account) external onlyOwner {
        minters[account] = true;
        emit MinterAdded(account);
    }

    /**
     * @notice Remove a minter
     */
    function removeMinter(address account) external onlyOwner {
        minters[account] = false;
        emit MinterRemoved(account);
    }

    /**
     * @notice Mint tokens for rewards (capped at MAX_SUPPLY)
     */
    function mint(address to, uint256 amount) external onlyMinter {
        require(totalSupply() + amount <= MAX_SUPPLY, "OTT: max supply exceeded");
        _mint(to, amount);
    }
}

contracts/TaskEscrow.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/token/ERC20/IERC20.sol";
import "@openzeppelin/contracts/token/ERC20/utils/SafeERC20.sol";
import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title TaskEscrow
 * @notice Escrow contract for OtherThing compute tasks
 * @dev Handles payment flow: deposit -> execute -> release/refund
 */
contract TaskEscrow is Ownable, ReentrancyGuard {
    using SafeERC20 for IERC20;

    IERC20 public immutable ottToken;

    uint256 public platformFeePercent = 5; // 5% platform fee
    uint256 public disputeTimeout = 24 hours;

    enum TaskStatus {
        Created,
        Assigned,
        Completed,
        Disputed,
        Refunded,
        Released
    }

    struct Task {
        address requester;
        bytes32 nodeId;
        uint256 amount;
        uint256 platformFee;
        TaskStatus status;
        bytes32 resultHash;      // IPFS hash of result
        uint256 createdAt;
        uint256 completedAt;
        string description;
    }

    // taskId => Task
    mapping(bytes32 => Task) public tasks;

    // Authorized task managers (orchestrators)
    mapping(address => bool) public managers;

    // Platform fee recipient
    address public feeRecipient;

    bytes32[] public allTaskIds;

    event TaskCreated(bytes32 indexed taskId, address indexed requester, uint256 amount);
    event TaskAssigned(bytes32 indexed taskId, bytes32 indexed nodeId);
    event TaskCompleted(bytes32 indexed taskId, bytes32 resultHash);
    event TaskDisputed(bytes32 indexed taskId, address indexed disputer);
    event TaskRefunded(bytes32 indexed taskId, uint256 amount);
    event TaskReleased(bytes32 indexed taskId, address indexed nodeOwner, uint256 amount);
    event ManagerAdded(address indexed manager);
    event ManagerRemoved(address indexed manager);

    constructor(address _ottToken, address _feeRecipient) Ownable(msg.sender) {
        ottToken = IERC20(_ottToken);
        feeRecipient = _feeRecipient;
    }

    modifier onlyManager() {
        require(managers[msg.sender] || msg.sender == owner(), "TaskEscrow: not a manager");
        _;
    }

    modifier onlyRequester(bytes32 taskId) {
        require(tasks[taskId].requester == msg.sender, "TaskEscrow: not requester");
        _;
    }

    /**
     * @notice Create a new task with escrowed payment
     * @param taskId Unique identifier for the task
     * @param amount Payment amount in OTT
     * @param description Task description (stored on-chain for transparency)
     */
    function createTask(
        bytes32 taskId,
        uint256 amount,
        string calldata description
    ) external nonReentrant {
        require(tasks[taskId].requester == address(0), "TaskEscrow: task exists");
        require(amount > 0, "TaskEscrow: zero amount");

        uint256 fee = (amount * platformFeePercent) / 100;
        uint256 total = amount + fee;

        ottToken.safeTransferFrom(msg.sender, address(this), total);

        tasks[taskId] = Task({
            requester: msg.sender,
            nodeId: bytes32(0),
            amount: amount,
            platformFee: fee,
            status: TaskStatus.Created,
            resultHash: bytes32(0),
            createdAt: block.timestamp,
            completedAt: 0,
            description: description
        });

        allTaskIds.push(taskId);

        emit TaskCreated(taskId, msg.sender, amount);
    }

    /**
     * @notice Assign a task to a node (called by orchestrator)
     */
    function assignTask(bytes32 taskId, bytes32 nodeId) external onlyManager {
        Task storage task = tasks[taskId];
        require(task.status == TaskStatus.Created, "TaskEscrow: invalid status");

        task.nodeId = nodeId;
        task.status = TaskStatus.Assigned;

        emit TaskAssigned(taskId, nodeId);
    }

    /**
     * @notice Mark task as completed (called by orchestrator)
     * @param resultHash IPFS CID of the result
     */
    function completeTask(bytes32 taskId, bytes32 resultHash) external onlyManager {
        Task storage task = tasks[taskId];
        require(task.status == TaskStatus.Assigned, "TaskEscrow: not assigned");

        task.resultHash = resultHash;
        task.status = TaskStatus.Completed;
        task.completedAt = block.timestamp;

        emit TaskCompleted(taskId, resultHash);
    }

    /**
     * @notice Release payment to node owner (after completion)
     * @param nodeOwner Address of the node owner to pay
     */
    function releasePayment(bytes32 taskId, address nodeOwner) external onlyManager nonReentrant {
        Task storage task = tasks[taskId];
        require(task.status == TaskStatus.Completed, "TaskEscrow: not completed");

        task.status = TaskStatus.Released;

        // Pay node owner
        ottToken.safeTransfer(nodeOwner, task.amount);

        // Pay platform fee
        if (task.platformFee > 0) {
            ottToken.safeTransfer(feeRecipient, task.platformFee);
        }

        emit TaskReleased(taskId, nodeOwner, task.amount);
    }

    /**
     * @notice Dispute a task (requester only, before release)
     */
    function disputeTask(bytes32 taskId) external onlyRequester(taskId) {
        Task storage task = tasks[taskId];
        require(
            task.status == TaskStatus.Assigned || task.status == TaskStatus.Completed,
            "TaskEscrow: cannot dispute"
        );

        task.status = TaskStatus.Disputed;

        emit TaskDisputed(taskId, msg.sender);
    }

    /**
     * @notice Refund a task (for cancelled/disputed tasks)
     */
    function refundTask(bytes32 taskId) external onlyManager nonReentrant {
        Task storage task = tasks[taskId];
        require(
            task.status == TaskStatus.Created ||
            task.status == TaskStatus.Disputed,
            "TaskEscrow: cannot refund"
        );

        task.status = TaskStatus.Refunded;

        // Refund full amount + fee to requester
        uint256 refundAmount = task.amount + task.platformFee;
        ottToken.safeTransfer(task.requester, refundAmount);

        emit TaskRefunded(taskId, refundAmount);
    }

    /**
     * @notice Cancel a task before assignment (requester only)
     */
    function cancelTask(bytes32 taskId) external nonReentrant onlyRequester(taskId) {
        Task storage task = tasks[taskId];
        require(task.status == TaskStatus.Created, "TaskEscrow: cannot cancel");

        task.status = TaskStatus.Refunded;

        uint256 refundAmount = task.amount + task.platformFee;
        ottToken.safeTransfer(msg.sender, refundAmount);

        emit TaskRefunded(taskId, refundAmount);
    }

    // Admin functions
    function addManager(address manager) external onlyOwner {
        managers[manager] = true;
        emit ManagerAdded(manager);
    }

    function removeManager(address manager) external onlyOwner {
        managers[manager] = false;
        emit ManagerRemoved(manager);
    }

    function setFeeRecipient(address _feeRecipient) external onlyOwner {
        feeRecipient = _feeRecipient;
    }

    function setPlatformFeePercent(uint256 _percent) external onlyOwner {
        require(_percent <= 20, "TaskEscrow: fee too high");
        platformFeePercent = _percent;
    }

    function setDisputeTimeout(uint256 _timeout) external onlyOwner {
        disputeTimeout = _timeout;
    }

    // View functions
    function getTask(bytes32 taskId) external view returns (Task memory) {
        return tasks[taskId];
    }

    function getTotalTasks() external view returns (uint256) {
        return allTaskIds.length;
    }
}

contracts/WorkspaceRegistry.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/ReentrancyGuard.sol";

/**
 * @title WorkspaceRegistry
 * @notice Decentralized workspace management - replaces centralized orchestrator
 * @dev Handles workspace creation, membership, and invite codes on-chain
 */
contract WorkspaceRegistry is Ownable, ReentrancyGuard {

    // ============ Enums ============

    enum MemberRole { Member, Admin, Owner }

    // ============ Structs ============

    struct Workspace {
        bytes32 id;
        string name;
        string description;
        address owner;
        uint256 createdAt;
        bool isPublic;
        bytes32 inviteCodeHash;  // keccak256 hash of invite code
        uint256 memberCount;
        bool exists;
    }

    struct Member {
        address memberAddress;
        uint256 joinedAt;
        MemberRole role;
        bool exists;
    }

    struct WorkspaceInfo {
        bytes32 id;
        string name;
        string description;
        address owner;
        uint256 createdAt;
        bool isPublic;
        uint256 memberCount;
    }

    // ============ State Variables ============

    // Workspace ID => Workspace
    mapping(bytes32 => Workspace) public workspaces;

    // Workspace ID => Member Address => Member
    mapping(bytes32 => mapping(address => Member)) public workspaceMembers;

    // Workspace ID => Array of member addresses
    mapping(bytes32 => address[]) private workspaceMemberList;

    // User Address => Array of workspace IDs they belong to
    mapping(address => bytes32[]) private userWorkspaces;

    // Track workspace count
    uint256 public workspaceCount;

    // All workspace IDs for enumeration
    bytes32[] private allWorkspaceIds;

    // ============ Events ============

    event WorkspaceCreated(
        bytes32 indexed workspaceId,
        string name,
        address indexed owner,
        bool isPublic
    );

    event MemberJoined(
        bytes32 indexed workspaceId,
        address indexed member,
        MemberRole role
    );

    event MemberLeft(
        bytes32 indexed workspaceId,
        address indexed member
    );

    event MemberRoleChanged(
        bytes32 indexed workspaceId,
        address indexed member,
        MemberRole newRole
    );

    event InviteCodeUpdated(bytes32 indexed workspaceId);

    event WorkspaceUpdated(
        bytes32 indexed workspaceId,
        string name,
        string description
    );

    event WorkspaceDeleted(
        bytes32 indexed workspaceId,
        address indexed owner
    );

    // ============ Errors ============

    error WorkspaceNotFound();
    error WorkspaceAlreadyExists();
    error AlreadyMember();
    error NotMember();
    error NotAuthorized();
    error InvalidInviteCode();
    error WorkspaceIsPrivate();
    error CannotLeaveAsOwner();
    error InvalidName();

    // ============ Constructor ============

    constructor() Ownable(msg.sender) {}

    // ============ External Functions ============

    /**
     * @notice Create a new workspace
     * @param name Workspace name
     * @param description Workspace description
     * @param isPublic Whether anyone can join without invite code
     * @param inviteCode Optional invite code for private workspaces (will be hashed)
     * @return workspaceId The ID of the created workspace
     */
    function createWorkspace(
        string memory name,
        string memory description,
        bool isPublic,
        string memory inviteCode
    ) external nonReentrant returns (bytes32 workspaceId) {
        if (bytes(name).length == 0 || bytes(name).length > 100) {
            revert InvalidName();
        }

        // Generate unique workspace ID
        workspaceId = keccak256(abi.encodePacked(
            msg.sender,
            name,
            block.timestamp,
            workspaceCount
        ));

        if (workspaces[workspaceId].exists) {
            revert WorkspaceAlreadyExists();
        }

        // Hash invite code if provided
        bytes32 inviteHash = bytes32(0);
        if (!isPublic && bytes(inviteCode).length > 0) {
            inviteHash = keccak256(abi.encodePacked(inviteCode));
        }

        // Create workspace
        workspaces[workspaceId] = Workspace({
            id: workspaceId,
            name: name,
            description: description,
            owner: msg.sender,
            createdAt: block.timestamp,
            isPublic: isPublic,
            inviteCodeHash: inviteHash,
            memberCount: 1,
            exists: true
        });

        // Add owner as first member
        workspaceMembers[workspaceId][msg.sender] = Member({
            memberAddress: msg.sender,
            joinedAt: block.timestamp,
            role: MemberRole.Owner,
            exists: true
        });

        workspaceMemberList[workspaceId].push(msg.sender);
        userWorkspaces[msg.sender].push(workspaceId);
        allWorkspaceIds.push(workspaceId);
        workspaceCount++;

        emit WorkspaceCreated(workspaceId, name, msg.sender, isPublic);
        emit MemberJoined(workspaceId, msg.sender, MemberRole.Owner);

        return workspaceId;
    }

    /**
     * @notice Join a public workspace
     * @param workspaceId The workspace to join
     */
    function joinPublicWorkspace(bytes32 workspaceId) external nonReentrant {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (!workspace.isPublic) revert WorkspaceIsPrivate();
        if (workspaceMembers[workspaceId][msg.sender].exists) revert AlreadyMember();

        _addMember(workspaceId, msg.sender, MemberRole.Member);
    }

    /**
     * @notice Join a workspace using an invite code
     * @param workspaceId The workspace to join
     * @param inviteCode The invite code
     */
    function joinWithInviteCode(
        bytes32 workspaceId,
        string memory inviteCode
    ) external nonReentrant {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (workspaceMembers[workspaceId][msg.sender].exists) revert AlreadyMember();

        // Verify invite code
        bytes32 providedHash = keccak256(abi.encodePacked(inviteCode));
        if (workspace.inviteCodeHash != providedHash) {
            revert InvalidInviteCode();
        }

        _addMember(workspaceId, msg.sender, MemberRole.Member);
    }

    /**
     * @notice Leave a workspace
     * @param workspaceId The workspace to leave
     */
    function leaveWorkspace(bytes32 workspaceId) external nonReentrant {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (!workspaceMembers[workspaceId][msg.sender].exists) revert NotMember();
        if (workspace.owner == msg.sender) revert CannotLeaveAsOwner();

        _removeMember(workspaceId, msg.sender);
    }

    /**
     * @notice Delete a workspace (owner only)
     * @param workspaceId The workspace to delete
     */
    function deleteWorkspace(bytes32 workspaceId) external nonReentrant {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (workspace.owner != msg.sender) revert NotAuthorized();

        // Remove all members
        address[] memory members = workspaceMemberList[workspaceId];
        for (uint256 i = 0; i < members.length; i++) {
            address member = members[i];

            // Remove from user's workspaces
            bytes32[] storage userWs = userWorkspaces[member];
            for (uint256 j = 0; j < userWs.length; j++) {
                if (userWs[j] == workspaceId) {
                    userWs[j] = userWs[userWs.length - 1];
                    userWs.pop();
                    break;
                }
            }

            // Delete member record
            delete workspaceMembers[workspaceId][member];
        }

        // Clear member list
        delete workspaceMemberList[workspaceId];

        // Remove from allWorkspaceIds
        for (uint256 i = 0; i < allWorkspaceIds.length; i++) {
            if (allWorkspaceIds[i] == workspaceId) {
                allWorkspaceIds[i] = allWorkspaceIds[allWorkspaceIds.length - 1];
                allWorkspaceIds.pop();
                break;
            }
        }

        // Mark as deleted (keep some data for history, but mark not exists)
        workspace.exists = false;
        workspaceCount--;

        emit WorkspaceDeleted(workspaceId, msg.sender);
    }

    /**
     * @notice Set or update the invite code for a workspace
     * @param workspaceId The workspace to update
     * @param newInviteCode The new invite code
     */
    function setInviteCode(
        bytes32 workspaceId,
        string memory newInviteCode
    ) external {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (!_isAdminOrOwner(workspaceId, msg.sender)) revert NotAuthorized();

        workspace.inviteCodeHash = keccak256(abi.encodePacked(newInviteCode));

        emit InviteCodeUpdated(workspaceId);
    }

    /**
     * @notice Update workspace details
     * @param workspaceId The workspace to update
     * @param name New name
     * @param description New description
     * @param isPublic New public status
     */
    function updateWorkspace(
        bytes32 workspaceId,
        string memory name,
        string memory description,
        bool isPublic
    ) external {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (workspace.owner != msg.sender) revert NotAuthorized();
        if (bytes(name).length == 0 || bytes(name).length > 100) revert InvalidName();

        workspace.name = name;
        workspace.description = description;
        workspace.isPublic = isPublic;

        emit WorkspaceUpdated(workspaceId, name, description);
    }

    /**
     * @notice Change a member's role
     * @param workspaceId The workspace
     * @param member The member to update
     * @param newRole The new role
     */
    function setMemberRole(
        bytes32 workspaceId,
        address member,
        MemberRole newRole
    ) external {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (workspace.owner != msg.sender) revert NotAuthorized();
        if (!workspaceMembers[workspaceId][member].exists) revert NotMember();
        if (newRole == MemberRole.Owner) revert NotAuthorized(); // Can't make someone else owner

        workspaceMembers[workspaceId][member].role = newRole;

        emit MemberRoleChanged(workspaceId, member, newRole);
    }

    /**
     * @notice Remove a member from workspace (admin/owner only)
     * @param workspaceId The workspace
     * @param member The member to remove
     */
    function removeMember(bytes32 workspaceId, address member) external {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (!_isAdminOrOwner(workspaceId, msg.sender)) revert NotAuthorized();
        if (!workspaceMembers[workspaceId][member].exists) revert NotMember();
        if (member == workspace.owner) revert NotAuthorized(); // Can't remove owner

        _removeMember(workspaceId, member);
    }

    /**
     * @notice Transfer workspace ownership
     * @param workspaceId The workspace
     * @param newOwner The new owner address
     */
    function transferOwnership(
        bytes32 workspaceId,
        address newOwner
    ) external {
        Workspace storage workspace = workspaces[workspaceId];

        if (!workspace.exists) revert WorkspaceNotFound();
        if (workspace.owner != msg.sender) revert NotAuthorized();

        // New owner must be a member
        if (!workspaceMembers[workspaceId][newOwner].exists) revert NotMember();

        // Update old owner role to Admin
        workspaceMembers[workspaceId][msg.sender].role = MemberRole.Admin;

        // Update new owner
        workspace.owner = newOwner;
        workspaceMembers[workspaceId][newOwner].role = MemberRole.Owner;

        emit MemberRoleChanged(workspaceId, msg.sender, MemberRole.Admin);
        emit MemberRoleChanged(workspaceId, newOwner, MemberRole.Owner);
    }

    // ============ View Functions ============

    /**
     * @notice Get workspace information
     * @param workspaceId The workspace ID
     * @return info Workspace information
     */
    function getWorkspace(bytes32 workspaceId) external view returns (WorkspaceInfo memory info) {
        Workspace storage workspace = workspaces[workspaceId];
        if (!workspace.exists) revert WorkspaceNotFound();

        return WorkspaceInfo({
            id: workspace.id,
            name: workspace.name,
            description: workspace.description,
            owner: workspace.owner,
            createdAt: workspace.createdAt,
            isPublic: workspace.isPublic,
            memberCount: workspace.memberCount
        });
    }

    /**
     * @notice Get all members of a workspace
     * @param workspaceId The workspace ID
     * @return members Array of member addresses
     */
    function getWorkspaceMembers(bytes32 workspaceId) external view returns (address[] memory) {
        if (!workspaces[workspaceId].exists) revert WorkspaceNotFound();
        return workspaceMemberList[workspaceId];
    }

    /**
     * @notice Get member details
     * @param workspaceId The workspace ID
     * @param member The member address
     * @return Member struct
     */
    function getMember(
        bytes32 workspaceId,
        address member
    ) external view returns (Member memory) {
        if (!workspaces[workspaceId].exists) revert WorkspaceNotFound();
        return workspaceMembers[workspaceId][member];
    }

    /**
     * @notice Check if address is a member of workspace
     * @param workspaceId The workspace ID
     * @param user The address to check
     * @return bool True if member
     */
    function isMember(bytes32 workspaceId, address user) external view returns (bool) {
        return workspaceMembers[workspaceId][user].exists;
    }

    /**
     * @notice Get all workspaces a user belongs to
     * @param user The user address
     * @return workspaceIds Array of workspace IDs
     */
    function getUserWorkspaces(address user) external view returns (bytes32[] memory) {
        return userWorkspaces[user];
    }

    /**
     * @notice Get all public workspaces
     * @return infos Array of workspace info
     */
    function getPublicWorkspaces() external view returns (WorkspaceInfo[] memory) {
        uint256 publicCount = 0;

        // Count public workspaces
        for (uint256 i = 0; i < allWorkspaceIds.length; i++) {
            if (workspaces[allWorkspaceIds[i]].isPublic) {
                publicCount++;
            }
        }

        // Build array
        WorkspaceInfo[] memory infos = new WorkspaceInfo[](publicCount);
        uint256 idx = 0;

        for (uint256 i = 0; i < allWorkspaceIds.length; i++) {
            Workspace storage ws = workspaces[allWorkspaceIds[i]];
            if (ws.isPublic) {
                infos[idx] = WorkspaceInfo({
                    id: ws.id,
                    name: ws.name,
                    description: ws.description,
                    owner: ws.owner,
                    createdAt: ws.createdAt,
                    isPublic: ws.isPublic,
                    memberCount: ws.memberCount
                });
                idx++;
            }
        }

        return infos;
    }

    /**
     * @notice Verify an invite code without joining
     * @param workspaceId The workspace ID
     * @param inviteCode The invite code to verify
     * @return valid True if invite code is valid
     */
    function verifyInviteCode(
        bytes32 workspaceId,
        string memory inviteCode
    ) external view returns (bool valid) {
        Workspace storage workspace = workspaces[workspaceId];
        if (!workspace.exists) return false;

        bytes32 providedHash = keccak256(abi.encodePacked(inviteCode));
        return workspace.inviteCodeHash == providedHash;
    }

    // ============ Internal Functions ============

    function _addMember(
        bytes32 workspaceId,
        address member,
        MemberRole role
    ) internal {
        workspaceMembers[workspaceId][member] = Member({
            memberAddress: member,
            joinedAt: block.timestamp,
            role: role,
            exists: true
        });

        workspaceMemberList[workspaceId].push(member);
        userWorkspaces[member].push(workspaceId);
        workspaces[workspaceId].memberCount++;

        emit MemberJoined(workspaceId, member, role);
    }

    function _removeMember(bytes32 workspaceId, address member) internal {
        // Remove from member mapping
        delete workspaceMembers[workspaceId][member];

        // Remove from member list
        address[] storage members = workspaceMemberList[workspaceId];
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == member) {
                members[i] = members[members.length - 1];
                members.pop();
                break;
            }
        }

        // Remove from user's workspaces
        bytes32[] storage userWs = userWorkspaces[member];
        for (uint256 i = 0; i < userWs.length; i++) {
            if (userWs[i] == workspaceId) {
                userWs[i] = userWs[userWs.length - 1];
                userWs.pop();
                break;
            }
        }

        workspaces[workspaceId].memberCount--;

        emit MemberLeft(workspaceId, member);
    }

    function _isAdminOrOwner(bytes32 workspaceId, address user) internal view returns (bool) {
        Member storage member = workspaceMembers[workspaceId][user];
        return member.exists && (member.role == MemberRole.Admin || member.role == MemberRole.Owner);
    }
}

